from pathlib import Path
import json,re,sys
root=Path('.').resolve()
window=root/'evidence/quality/repair-window-67-20261005'
errors=[]
# Validate UTF-8 for the complete installed snapshot and published text evidence.
text_files=[]
for base in [window/'orchestration',window/'publication']:
    text_files.extend(p for p in base.rglob('*') if p.is_file())
text_files += [window/'orchestration-pack-manifest.json',window/'PUBLICATION.md',root/'handoff.md']
for p in text_files:
    try: p.read_text('utf-8')
    except UnicodeDecodeError as exc: errors.append(f'non-UTF-8 {p}: {exc}')
# Parse every installed/published JSON file.
json_files=[p for p in text_files if p.suffix=='.json']
json_files += [
 root/'evidence/production-review-v2-lite/catalog/manifest.json',
 root/'i18n/quality/production-review-v2-lite/catalog-v1.schema.json',
 root/'i18n/quality/production-review-v2-lite/policy-v1.json',
 root/'evidence/production-review-v2-lite/migrations/a0f4f2206d3ff692ae44f032e55b69e282b42d9240718e6da31d6bfd5b1a3038.json',
]
for p in dict.fromkeys(json_files):
    try: json.loads(p.read_text('utf-8'))
    except Exception as exc: errors.append(f'invalid JSON {p}: {exc}')
# Resolve local Markdown links in authored and frozen handoff documents.
link_count=0
for doc in [window/'PUBLICATION.md',root/'handoff.md']:
    text=doc.read_text('utf-8')
    for href in re.findall(r'\[[^\]]+\]\(([^)]+)\)',text):
        if href.startswith(('http://','https://','#')): continue
        clean=href.strip('<>').split('#',1)[0]
        if not clean: continue
        link_count+=1
        if not (doc.parent/clean).resolve().exists(): errors.append(f'broken link {doc}: {href}')
manifest=json.loads((root/'evidence/production-review-v2-lite/catalog/manifest.json').read_text())
migration=json.loads((root/'.artifacts/i18n/repair-window/window67-20261005-migration.json').read_text())
print('utf8_files_verified',len(dict.fromkeys(text_files)))
print('json_files_parsed',len(dict.fromkeys(json_files)))
print('local_markdown_links_verified',link_count)
print('catalog_manifest_selected_fields')
for key in ('catalog_id','catalog_sha256','catalog_identity','entries_count','exclusions_count'):
    if key in manifest: print(key,manifest[key])
print('migration_selected_fields')
# Recursively report the specified counters without changing/re-running migration.
def walk(x,p=''):
    if isinstance(x,dict):
        for k,v in x.items():
            q=f'{p}.{k}' if p else k
            if k in {'revision_changed','unchanged','queued_successors','ambiguous','unmapped'}: print(q,v)
            walk(v,q)
    elif isinstance(x,list):
        for i,v in enumerate(x): walk(v,f'{p}[{i}]')
walk(migration)
print('errors',len(errors))
for e in errors: print('ERROR',e)
if errors: sys.exit(1)
